<script setup>import {onMounted,ref} from 'vue';import client from '@/api/client';import {useRouter} from 'vue-router';const router=useRouter(),vehicles=ref([]),vehicle_id=ref(''),complaint=ref(''),error=ref('');onMounted(async()=>{vehicles.value=(await client.get('/vehicles')).data.data});async function save(){try{const r=await client.post('/work-orders',{vehicle_id:vehicle_id.value,complaint:complaint.value});router.push(`/work-orders/${r.data.data.id}/ticket`)}catch(e){error.value=e.response?.data?.message||'Pendaftaran gagal.'}}</script><template><main><h1 class="text-2xl font-bold text-forest">Daftar Kendaraan</h1><div v-if="error" class="service-alert">{{error}}</div><label class="mb-1 block font-semibold text-ink">Kendaraan<select v-model="vehicle_id" class="service-input"><option value="">Pilih kendaraan</option><option v-for="v in vehicles" :value="v.id">{{v.plate_number}} - {{v.brand}} {{v.model}}</option></select></label><label class="mb-1 block font-semibold text-ink">Keluhan<textarea v-model="complaint" class="service-input"/></label><button class="service-primary" @click="save">Daftarkan</button></main></template>